        :param textnum: string, the word string to be converted
        :return: string, the final converted integer string
        """
    textnum = textnum.lower()
    current_num = 0
    position = 0
    is_reading_decimal = False
    for word in textnum.split():
        if word in self.numwords:
            if is_reading_decimal:
                current_num += self.numwords[word][0] * 10 ** position
                is_reading_decimal = False
            else:
                current_num += self.numwords[word][0]
            position += self.numwords[word][1]
        elif word in self.ordinal_words:
            if position > 0:
                current_num += self.numwords[self.ordinal_words[word] + 'th'][0] * 10 ** position
            else:
                current_num += self.numwords[self.ordinal_words[word]][0]
            position += self.numwords[self.ordinal_words[word]][1]
        elif word == 'point':
            is_reading_decimal = True
            position = 0
        else:
            return 'Invalid input'
    return str(current_num)
